import manifest from "./manifest.json";

// Generated by scripts/gen-manifest.mjs on every build.
const files = manifest as string[];

/** Returns the first existing file (as a public URL) from a list of candidates. */
export function firstExisting(candidates: string[]): string | null {
  for (const c of candidates) {
    if (files.includes(c)) return "/" + c;
  }
  return null;
}

export type MediaItem = { src: string; type: "image" | "video"; name: string };

const imageExt = /\.(jpe?g|png|webp|avif)$/i;
const videoExt = /\.(mp4|webm|mov)$/i;

/** Lists photos and videos dropped into public/media/<folder>. */
export function listMedia(folder: string): MediaItem[] {
  const prefix = `media/${folder}/`;
  return files
    .filter((f) => f.startsWith(prefix))
    .map((f): MediaItem | null => {
      const name = f.slice(prefix.length);
      const src = `/${prefix}${encodeURIComponent(name)}`;
      if (imageExt.test(name)) return { src, type: "image", name };
      if (videoExt.test(name)) return { src, type: "video", name };
      return null;
    })
    .filter((m): m is MediaItem => m !== null);
}
